class Solution {
    public int findNthDigit(int n) {
        long length = 1;
        long count = 9;
        long start = 1;
        while (n > length * count) {
            n -= (int)(length * count);
            length++;
            count *= 10;
            start *= 10;
        }
        start += (n - 1) / length;
        String s = Long.toString(start);
        return s.charAt((int)((n - 1) % length)) - '0';
    }
}

var findNthDigit = function(n) {
    let length = 1;
    let count = 9;
    let start = 1;
    while (n > length * count) {
        n -= length * count;
        length++;
        count *= 10;
        start *= 10;
    }
    start += Math.floor((n - 1) / length);
    const s = String(start);
    return Number(s[(n - 1) % length]);
};
